// n8n Code Node
// Input: items (array de objetos JSON)
// Output:
//   1) items filtrados (únicos por id_paciente)
//   2) un segundo item con la lista de ids_paciente eliminados

const seen = new Set();
const unique = [];
const removedIds = [];

for (const item of items) {
  const data = item.json;

  if (!seen.has(data.id_paciente)) {
    seen.add(data.id_paciente);
    unique.push(item);
  } else {
    removedIds.push(data.id_paciente);
  }
}

// El flujo debe retornar un array de items.
// Devolvemos los items únicos + un item final con los ids eliminados.
return [
  ...unique,
/*  {
    json: {
      removed_ids: removedIds
    }
  }*/
];

