const date = new Date();
// Ajustamos a la zona horaria de Montevideo
const uruguayTime = new Date(date.toLocaleString('en-US', { timeZone: 'America/Montevideo' }));
// Restamos un día (en ms)
uruguayTime.setDate(uruguayTime.getDate() - 1);
// Formateamos YYYY-MM-DD
const year = uruguayTime.getFullYear();
const month = String(uruguayTime.getMonth() + 1).padStart(2, '0');
const day = String(uruguayTime.getDate()).padStart(2, '0');
return [{ json: { ayer: `${year}-${month}-${day}` } }];

const rows = $input.all();

const CONFIRMACION = [
  'Confirmado por pcte. vía WhatsApp',
  'Confirmado por teléfono',
  'Confirmado por Whatsapp'
];
const NOTIF_WA = 'Notif. automática vía WhatsApp';
const NO_ASISTIO = 'No asistió';
const LLEGO = ['Atendido', 'Atendiéndose', 'En sala de espera', 'No asistió'];

// 1. Agrupar por # Cita
const citasPorId = {};
for (const row of rows) {
  const d = row.json;
  const idCita = String(d['# Cita'] || d['Numero Cita'] || '');
  if (!idCita) continue;
  if (!citasPorId[idCita]) {
    citasPorId[idCita] = {
      pacienteId: String(d['# Paciente'] || d['Numero Paciente'] || ''),
      nombrePaciente: ((d['Nombre Paciente'] || '') + ' ' + (d['Apellidos Paciente'] || '')).trim(),
      mesCita: d['Mes Cita'] || '',
      añoCita: d['Año Cita'] || '',
      estados: [],
      fechas: []
    };
  }
  citasPorId[idCita].estados.push(String(d['Estado Cita'] || ''));
  citasPorId[idCita].fechas.push(d['Fecha Estado Cita'] || '');
}

// 2. Clasificar cada cita
const citas = Object.values(citasPorId).map(c => {
  const noAsistioIdx = c.estados.lastIndexOf(NO_ASISTIO);
  return {
    ...c,
    llegoAlDia:    c.estados.some(e => LLEGO.includes(e)),
    fueConfirmada: c.estados.some(e => CONFIRMACION.includes(e)),
    fueNotifWA:    c.estados.includes(NOTIF_WA),
    noAsistio:     noAsistioIdx >= 0,
    fechaNoAsistio: noAsistioIdx >= 0 ? String(c.fechas[noAsistioIdx]).substring(0, 10) : ''
  };
});

// 3. Métricas agregadas
const llegaron    = citas.filter(c => c.llegoAlDia);
const confirmadas = citas.filter(c => c.fueConfirmada);
const notifWA     = citas.filter(c => c.fueNotifWA);

const totalLlegaron    = llegaron.length;
const totalNoAsistio   = llegaron.filter(c => c.noAsistio).length;
const totalConfirmadas = confirmadas.length;
const confirmNoAsistio = confirmadas.filter(c => c.noAsistio).length;
const totalNotifWA     = notifWA.length;
const notifWANoAsistio = notifWA.filter(c => c.noAsistio).length;

const fmt = (n, d) => d > 0 ? (n / d * 100).toFixed(1) + '%' : '-';

const meses = [...new Set(citas.map(c => c.mesCita).filter(Boolean))].join(', ');
const años  = [...new Set(citas.map(c => String(c.añoCita)).filter(Boolean))].join(', ');
const periodo = (meses + ' ' + años).trim();
const now = new Date().toLocaleString('es-UY', { timeZone: 'America/Montevideo' });

// 4. Resumen por paciente
const porPaciente = {};
for (const cita of citas) {
  const pid = cita.pacienteId;
  if (!pid) continue;
  if (!porPaciente[pid]) {
    porPaciente[pid] = {
      ID: pid,
      Nombre: cita.nombrePaciente,
      Inasistencias: 0,
      'Fecha Ultima Inasistencia': '',
      'Confirmo y No Asistio': 0,
      'Notif WA y No Asistio': 0
    };
  }
  if (cita.noAsistio) {
    const p = porPaciente[pid];
    p.Inasistencias++;
    if (!p['Fecha Ultima Inasistencia'] || cita.fechaNoAsistio > p['Fecha Ultima Inasistencia']) {
      p['Fecha Ultima Inasistencia'] = cita.fechaNoAsistio;
    }
    if (cita.fueConfirmada) p['Confirmo y No Asistio']++;
    if (cita.fueNotifWA)    p['Notif WA y No Asistio']++;
  }
}

const pacientes = Object.values(porPaciente)
  .filter(p => p.Inasistencias > 0)
  .sort((a, b) => b.Inasistencias - a.Inasistencias);

return [{
  json: {
    resumen: {
      periodo,
      ultimaActualizacion: now,
      totalLlegaron,
      totalNoAsistio,
      pctGeneral: fmt(totalNoAsistio, totalLlegaron),
      totalConfirmadas,
      confirmNoAsistio,
      pctConfirm: fmt(confirmNoAsistio, totalConfirmadas),
      totalNotifWA,
      notifWANoAsistio,
      pctWA: fmt(notifWANoAsistio, totalNotifWA)
    },
    pacientes
  }
}];
